// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ScheduledMeeting) predicate.ScheduledMeeting {
	return predicate.ScheduledMeeting(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ScheduledMeeting) predicate.ScheduledMeeting {
	return predicate.ScheduledMeeting(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ScheduledMeeting) predicate.ScheduledMeeting {
	return predicate.ScheduledMeeting(sql.NotPredicates(p))
}
